"""`Gag Mouth Atlas`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = 'Gag Mouth Atlas'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Color', 'NodeSocketColor')
    t.socket('OUTPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Mouth', 'NodeSocketMenu')
    t.socket('INPUT', 'Flip', 'NodeSocketBool', description='Mirror the mouth texture left-right')

    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1400.0, 0.0),
    })
    t.node('ShaderNodeTexCoord', 'Texture Coordinate', props={
        'location': (-1400.0, -250.0),
    })
    t.node('ShaderNodeSeparateXYZ', 'Separate XYZ', props={
        'location': (-1200.0, -250.0),
    })
    t.node('ShaderNodeMath', 'Math', inputs={'Value': 1.0}, props={
        'location': (-1000.0, -350.0),
        'label': '1 - U',
        'operation': 'SUBTRACT',
    })
    t.node('ShaderNodeMix', 'Mix', props={
        'location': (-800.0, -200.0),
        'label': 'Flip U',
    })
    t.node('ShaderNodeCombineXYZ', 'Combine XYZ', props={
        'location': (-600.0, -250.0),
    })
    t.node('ShaderNodeVectorMath', 'Vector Math', inputs={'Vector_001': (0.125, 0.14285715, 1.0)}, props={
        'location': (-400.0, -250.0),
        'label': 'Scale to one cell',
        'operation': 'MULTIPLY',
    })
